export class Unauthorized extends Error {}

/** A request the core refused; `message` is the core's own explanation when it gave one. */
export class Refused extends Error {
  readonly status: number

  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

async function call(method: string, path: string, body?: unknown, keepalive = false): Promise<Response> {
  const response = await fetch(path, {
    method,
    keepalive,
    credentials: 'same-origin',
    headers: body === undefined ? {} : { 'content-type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
  if (response.status === 401) throw new Unauthorized()
  if (!response.ok) throw new Refused(response.status, await problem(response, method, path))
  return response
}

/** The `{error}` text of a failed response, or a generic sentence when the body has none. */
async function problem(response: Response, method: string, path: string): Promise<string> {
  try {
    const body = (await response.json()) as Partial<Schemas['Problem']>
    if (typeof body.error === 'string' && body.error) return body.error
  } catch {
    // Not JSON: fall through.
  }
  return `${method} ${path} failed with ${response.status}`
}

async function json<T>(method: string, path: string, body?: unknown): Promise<T> {
  return (await (await call(method, path, body)).json()) as T
}

export async function currentAgent(): Promise<Agent | null> {
  try {
    return await json<Agent>('GET', '/api/session')
  } catch (error) {
    if (error instanceof Unauthorized) return null
    throw error
  }
}

/** Returns false when the e-mail or the password is wrong. */
export async function signIn(email: string, password: string): Promise<boolean> {
  try {
    await call('POST', '/api/session', { email, password })
    return true
  } catch (error) {
    if (error instanceof Unauthorized) return false
    throw error
  }
}

export async function signOut(): Promise<void> {
  await call('DELETE', '/api/session')
}

/**
 * Changes the signed-in agent's own password; their other sessions end. Refused (403) when the
 * current password is wrong, and (409) when the new one is too short.
 */
export async function changeOwnPassword(currentPassword: string, newPassword: string): Promise<void> {
  const request: Schemas['PasswordChange'] = { current_password: currentPassword, new_password: newPassword }
  await call('PUT', '/api/session/password', request)
}

/** What the ticket list is narrowed to; a field left out or empty does not narrow it. */
export interface TicketQuery {
  /** Comma-separated states. */
  state?: string
  /** `me`, `none` or an agent's id. */
  assignee?: string
  customer?: string
  /** A requester's id. */
  requester?: string
  q?: string
}

export function listTickets(query: TicketQuery = {}): Promise<TicketSummary[]> {
  const params = new URLSearchParams()
  for (const [name, value] of Object.entries(query)) if (value) params.set(name, value)
  const search = params.toString()
  return json('GET', search ? `/api/tickets?${search}` : '/api/tickets')
}

export function listInbox(): Promise<InboxMessage[]> {
  return json('GET', '/api/inbox')
}

export function listAgents(): Promise<AgentEntry[]> {
  return json('GET', '/api/agents')
}

/** Customers that are not offboarded. */
export function listCustomers(): Promise<CustomerEntry[]> {
  return json('GET', '/api/customers')
}

/**
 * Opens a ticket by hand, e.g. after a phone call; returns its number. A new requester address is
 * registered with the customer; `note` becomes an internal note recording what was said.
 */
export async function openTicket(request: Schemas['NewTicket']): Promise<number> {
  return (await json<Schemas['OpenedTicket']>('POST', '/api/tickets', request)).number
}

/** Every customer, offboarded ones included (last), with counts. */
export function listAllCustomers(): Promise<CustomerSummary[]> {
  return json('GET', '/api/customers/all')
}

const ticketPath = (number: number) => `/api/tickets/${encodeURIComponent(number)}`
const inboxPath = (id: string) => `/api/inbox/${encodeURIComponent(id)}`
const customerPath = (id: string) => `/api/customers/${encodeURIComponent(id)}`
const assetPath = (id: string) => `/api/assets/${encodeURIComponent(id)}`
const servicePath = (id: string) => `/api/services/${encodeURIComponent(id)}`

export function getTicket(number: number): Promise<TicketDetail> {
  return json('GET', ticketPath(number))
}

/** A note is internal: it is never sent to anyone. */
export async function addNote(number: number, body: string): Promise<void> {
  const request: Schemas['NewNote'] = { body }
  await call('POST', `${ticketPath(number)}/notes`, request)
}

/**
 * Queues a message to the requester; the ticket then moves to `then` (the core's default is
 * waiting). It goes where the requester last wrote from on the ticket; on a ticket they have not
 * written on, `to` is the address the agent picked among theirs.
 */
export async function reply(number: number, body: string, then?: TicketState, to?: string | null): Promise<void> {
  const request: Schemas['NewReply'] = { body, then, to }
  await call('POST', `${ticketPath(number)}/replies`, request)
}

/** The signed-in agent's unsent draft on the ticket, or null. */
export function getDraft(number: number): Promise<Draft | null> {
  return json('GET', `${ticketPath(number)}/draft`)
}

/**
 * Saves the signed-in agent's draft; an empty body removes it. With `keepalive` the request
 * outlives the page, for saving while it is being left.
 */
export async function saveDraft(number: number, mode: DraftMode, body: string, keepalive = false): Promise<void> {
  const request: Schemas['DraftChange'] = { mode, body }
  await call('PUT', `${ticketPath(number)}/draft`, request, keepalive)
}

export async function setPriority(number: number, priority: Priority): Promise<void> {
  const request: Schemas['PriorityChange'] = { priority }
  await call('PUT', `${ticketPath(number)}/priority`, request)
}

/**
 * Accepts a proposal of an add-on: it is applied as if the agent did it. A draft reply comes back in
 * `reply_body` for the composer; nothing is sent.
 */
export function acceptProposal(id: string): Promise<Schemas['Accepted']> {
  return json('POST', `/api/proposals/${encodeURIComponent(id)}/accept`)
}

export async function discardProposal(id: string): Promise<void> {
  await call('POST', `/api/proposals/${encodeURIComponent(id)}/discard`)
}

export async function setState(number: number, state: TicketState): Promise<void> {
  const request: Schemas['StateChange'] = { state }
  await call('PUT', `${ticketPath(number)}/state`, request)
}

/** `agentId` null leaves the ticket unassigned. */
export async function setAssignee(number: number, agentId: string | null): Promise<void> {
  const request: Schemas['AssigneeChange'] = { agent_id: agentId }
  await call('PUT', `${ticketPath(number)}/assignee`, request)
}

/**
 * Moves a ticket to another customer. With `requester` "move", the requester moves too and takes
 * all of their tickets along; with "remove", the requester leaves this ticket. Returns how many
 * tickets moved and how many asset and service links were removed for not fitting the new customer.
 */
export function moveTicket(
  number: number,
  customerId: string,
  requester: Schemas['RequesterMove'],
): Promise<Moved> {
  const request: Schemas['CustomerChange'] = { customer_id: customerId, requester }
  return json('PUT', `${ticketPath(number)}/customer`, request)
}

